    LANGUAGE_WRAPPER = 'Let base = {base} > 1 be an integer and n = {n} be a positive integer. Define three quantities as follows:\n- x = ({base}^{r1} - 1) / product_{k=1}^{n} ( {base}^{(r1/2^k)} + 1 )\n- y = ({base}^{r2} - 1) / product_{k=1}^{n} ( {base}^{(r2/2^k)} + 1 )\n- z = ({base}^{r3} - 1) / product_{k=1}^{n} ( {base}^{(r3/2^k)} + 1 )\nEvaluate the exact value of the expression\n[ (xy + x + y + 1)(xz + x + z + 1)(yz + y + z + 1) / (xyz + xy + yz + zx + x + y + z + 1) ]^{m}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate base, n, r1, r2, r3, and m so that the final answer is base**K with 3 <= K <= 40.
def v2(x):
    c = 0
    while x > 0 and x % 2 == 0:
        x //= 2
        c += 1
    return c
for _ in range(1000):
    base = rng.randint(2, 9)
    n = rng.randint(3, 6)
    r1 = rng.randint(1, 40)
    r2 = rng.randint(1, 40)
    r3 = rng.randint(1, 40)
    s = r1 + r2 + r3
    d = 1 << n
    vs = v2(s)
    needed = 1 << max(0, n - vs)
    odd_part = s >> vs  # s / 2^{v2(s)}
    if odd_part == 0:
        continue
    # We want K = (s*m)/2^n = odd_part * t to be between 3 and 40
    lb_t = (3 + odd_part - 1) // odd_part
    ub_t = 40 // odd_part
    if ub_t < lb_t or ub_t <= 0:
        continue
    t = rng.randint(lb_t, min(ub_t, 6))  # cap t to keep m moderate
    m = needed * t
    K = (s * m) // d
    if (s * m) % d != 0:
        continue
    if 3 <= K <= 40:
        return {
            'base': base,
            'n': n,
            'r1': r1,
            'r2': r2,
            'r3': r3,
            'm': m
        }
# Fallback (should not usually occur)
# Choose a deterministic safe config
base = 3
n = 3
r1, r2, r3 = 1, 2, 2
s = r1 + r2 + r3
d = 1 << n
# s=5, need m multiple of 2^{3-0}=8 so that K = 5*m/8 integer
m = 8
return {'base': base, 'n': n, 'r1': r1, 'r2': r2, 'r3': r3, 'm': m}

    def verifier(assign):
# Recompute and validate, then return (True, answer) or (False, None)
try:
    base = int(assign['base'])
    n = int(assign['n'])
    r1 = int(assign['r1'])
    r2 = int(assign['r2'])
    r3 = int(assign['r3'])
    m = int(assign['m'])
except Exception:
    # Missing or non-integer inputs
    return (False, None)
if not (base > 1 and n >= 3 and r1 >= 1 and r2 >= 1 and r3 >= 1 and m >= 1):
    # Domain constraints violated
    return (False, None)
d = 1 << n
s = r1 + r2 + r3
# Ensure the exponent is an integer
if (s * m) % d != 0:
    return (False, None)
K = (s * m) // d
# Enforce non-triviality to avoid degenerate/easy cases
if K < 3 or K > 40:
    return (False, None)
# The expression simplifies to [(x+1)(y+1)(z+1)]^m = base^{(s*m)/2^n}
answer = pow(base, K)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

